// Recovered from the July 20 Deckplate/AI Lantern session (regenerated by transcript replay).
// Forge + Chat verification: gate, overlay lifecycle, boot persistence,
// safe mode, chat tool-loop, proposal routing — against the delivered inner.
const fs = require('fs'); const path = require('path');
const { JSDOM } = require("jsdom");
const html = fs.readFileSync(require("path").join(__dirname, "..", "src", "lantern.inner.html"),'utf8');
let fails = 0;
const check = (n,c) => { console.log((c?'PASS':'FAIL')+'  '+n); if(!c) fails++; };
const tick = (w,ms) => new Promise(r=>w.setTimeout(r,ms||30));
function boot(opts) {
  const dom = new JSDOM(html, Object.assign({ runScripts:'dangerously', url:'http://localhost/', pretendToBeVisual:true }, opts));
  const w = dom.window;
  w.HTMLMediaElement.prototype.play = function(){ return Promise.resolve(); };
  w.HTMLMediaElement.prototype.pause = function(){};
  return dom;
}
(async () => {
  // ---------- instance 1: gate + lifecycle + chat ----------
  let dom = boot(), w = dom.window, d = w.document;
  d.dispatchEvent(new w.Event('DOMContentLoaded',{bubbles:true}));
  await tick(w);
  const L = w.Lantern, F = L.forge, T = L.selftest;
  const t0 = T.run();
  check('selftest registry all green on clean boot ('+t0.pass+' tests)', t0.fail.length === 0 && t0.pass >= 8);
  const names = F.list().map(x=>x.name);
  check('forge sees the whole live module set ('+names.length+')', names.length >= 170 && names.includes('CORE') && names.includes('DECKPLATE_TAGS') && names.includes('ASSIST_CARDS'));
  const cardText = F.read('ASSIST_CARDS');
  check('read returns marker-bounded module text', /MODULE: ASSIST_CARDS - START/.test(cardText) && /MODULE: ASSIST_CARDS - END/.test(cardText) && /orbit-period/.test(cardText));

  // gate rejections
  check('gate rejects wrong-name text', F.checkText('ASSIST_CARDS', F.read('ASSIST_CATALOG')).ok === false);
  check('gate rejects broken syntax', F.checkText('ASSIST_CARDS', cardText.replace('window.Lantern.assistCards = [', 'window.Lantern.assistCards = [[')).ok === false);

  // stage + activate a real improvement: one new card
  const newCard = '    { id: "forge-proof", ask: "Forge proof card?", kw: ["zzforgeproof"], pre: "",\n' +
                  '      slots: [{ k: "x", label: "X", unit: "" }],\n' +
                  '      compose: "={x}*2", out: "doubled" },\n';
  const modText = cardText.replace('    { id: "orbit-period"', newCard + '    { id: "orbit-period"');
  const st = F.stage('ASSIST_CARDS', modText, 'smoke');
  check('stage passes the gate', st.ok === true);
  check('staged does not apply yet', L.assistCards.filter(c=>c.id==='forge-proof').length === 0);
  const act = F.activate('ASSIST_CARDS');
  check('activate passes selftests and applies', act.ok === true && L.assistCards.some(c=>c.id==='forge-proof'));
  check('assist matches the forged card', L.assist.match('zzforgeproof please')[0].id === 'forge-proof');
  check('forged card computes', Math.abs(L.assist.run(L.assist.fill(L.assistCards.find(c=>c.id==='forge-proof'), {x:21})).value - 42) < 1e-9);

  // failing overlay: evaluates but breaks a selftest -> FAILED, not persisted as active
  const sabotage = cardText.replace(/compose: "=ORBITT\(CONVERT\(\{alt_km\}\+6371,\\"km\\",\\"m\\"\)\)\/60"/,
                                    'compose: "=1"');
  const st2 = F.stage('ASSIST_CARDS', sabotage, 'sabotage');
  const act2 = F.activate('ASSIST_CARDS');
  check('gate catches a semantically broken overlay via selftests', st2.ok === true && act2.ok === false && F.overlays()['ASSIST_CARDS'].status === 'failed');
  const rb = F.rollback('ASSIST_CARDS');
  check('rollback restores the good version and re-passes', rb.ok === true && L.assistCards.some(c=>c.id==='forge-proof'));

  // brand-new module via the same path
  const newMod = '// ===========================================================================\n' +
    '// MODULE: FORGE_PROOF_CELLS - START\n// Depends: FORMULA\n// Exports: (registers TWICE)\n' +
    '// ===========================================================================\n' +
    '(function () {\n  Lantern.formula.register("TWICE", function (a) { return 2 * parseFloat(a[0]); });\n' +
    '  Lantern.selftest.add("twice", function () { return Lantern.formula.evaluate("TWICE(21)") === 42; });\n})();\n' +
    '// ===========================================================================\n' +
    '// MODULE: FORGE_PROOF_CELLS - END\n' +
    '// ===========================================================================\n';
  const st3 = F.stage('FORGE_PROOF_CELLS', newMod, 'new module');
  const act3 = F.activate('FORGE_PROOF_CELLS');
  check('new module stages, activates, self-tests', st3.ok && act3.ok && L.formula.evaluate('TWICE(4)') === 8);
  check('new module appears in list as new', F.list().some(m=>m.name==='FORGE_PROOF_CELLS' && m.newModule));

  // capture persisted store for the boot test
  const persisted = {};
  for (let i=0;i<w.localStorage.length;i++){ const k=w.localStorage.key(i); persisted[k]=w.localStorage.getItem(k); }

  // chat with a stubbed 2-round model
  let calls = 0;
  w.fetch = async (url, opts) => {
    calls++;
    const body = JSON.parse(opts.body);
    if (calls === 1) {
      return { ok:true, json: async()=>({ choices:[{ message:{ content:'=ORBITT(CONVERT(420+6371,"km","m"))/60' } }] }) };
    }
    const fedBack = body.messages[body.messages.length-1].content;
    if (!/TOOL RESULTS/.test(fedBack)) return { ok:true, json: async()=>({ choices:[{ message:{ content:'ANSWER: protocol error' } }] }) };
    return { ok:true, json: async()=>({ choices:[{ message:{ content:
      'ANSWER: about 92.8 minutes per orbit\nPROPOSE MODULE: ASSIST_CATALOG\n' + F.read('ASSIST_CATALOG') + 'END PROPOSAL' } }] }) };
  };
  w.location.hash = 'chat';
  w.dispatchEvent(new w.Event('hashchange'));
  await tick(w,40);
  const qin = d.querySelector('input[aria-label="Message"]');
  check('chat app mounted', !!qin);
  qin.value = 'how long does the iss take to orbit at 420 km';
  ;[...d.querySelectorAll('button')].find(b=>b.textContent==='Send').click();
  await tick(w,80); await tick(w,80);
  check('tool loop ran two model rounds', calls === 2);
  check('tool results bubble shows verified 92.8', /92\.8/.test(d.body.textContent));
  check('final ANSWER rendered', /about 92\.8 minutes per orbit/.test(d.body.textContent));
  check('system prompt carries contract + catalog', /PROPOSE MODULE/.test(w.Lantern.CHAT.buildSystem()) && /MOLARMASS/.test(w.Lantern.CHAT.buildSystem()));
  check('proposal routed to forge as staged', F.overlays()['ASSIST_CATALOG'] && F.overlays()['ASSIST_CATALOG'].status === 'staged' && /staged for review/i.test(d.body.textContent));
  check('staged proposal not applied by chat', t0.fail.length === 0); // catalog unchanged in effect

  // ---------- instance 2: boot persistence of active overlays ----------
  dom = boot({ beforeParse(win){ for (const k in persisted) win.localStorage.setItem(k, persisted[k]); } });
  w = dom.window; d = w.document;
  d.dispatchEvent(new w.Event('DOMContentLoaded',{bubbles:true}));
  await tick(w,40);
  check('second boot re-applies active overlays (forged card present)', w.Lantern.assistCards.some(c=>c.id==='forge-proof'));
  check('second boot re-applies new module (TWICE works)', w.Lantern.formula.evaluate('TWICE(10)') === 20);
  check('failed/staged overlays did NOT apply on boot', w.Lantern.selftest.run().fail.length === 0);
  check('bootlog records applications', w.Lantern.forge.bootlog.join(' ').includes('ASSIST_CARDS'));

  // ---------- instance 3: safe mode skips everything ----------
  dom = boot({ url:'http://localhost/?safe=1', beforeParse(win){ for (const k in persisted) win.localStorage.setItem(k, persisted[k]); } });
  w = dom.window; d = w.document;
  d.dispatchEvent(new w.Event('DOMContentLoaded',{bubbles:true}));
  await tick(w,40);
  check('?safe=1 skips overlays', !w.Lantern.assistCards.some(c=>c.id==='forge-proof') && w.Lantern.forge.safeMode === true);

  console.log(fails ? 'FORGE/CHAT FAILURES: '+fails : 'ALL FORGE + CHAT TESTS PASS');
  process.exit(fails?1:0);
})().catch(e=>{console.error('CRASH',e);process.exit(1);});
